import { countText } from '@/shared/text'
import { runsText } from '../ir'
import type { ManuscriptBlock, ManuscriptIR } from '../ir'

/**
 * The manuscript's word count as the title page states it (before rounding): the words of the IR's
 * text runs (front matter, chapter numbers and titles, every paragraph), counted by the app's word
 * counter. List markers are generated by the renderer and footnotes are not body text, so neither
 * counts: this equals the live count's `body.words` (`countManuscript`) on the same document.
 */
export function manuscriptWordCount(ir: ManuscriptIR): number {
  let words = 0
  const blocks = (list: readonly ManuscriptBlock[]) => {
    for (const b of list) if (b.kind === 'paragraph') words += countText(runsText(b.runs)).words
  }
  blocks(ir.frontMatter)
  for (const c of ir.chapters) {
    words += countText(runsText(c.number)).words + countText(runsText(c.title)).words
    blocks(c.blocks)
  }
  return words
}
